// AssertLogContract runs every generated check against every declared subject.
//
//	Subjects: declare each with LogSubject
//	Extend:   LogOnAppend, LogOnReplay
//	Drop:     LogWithout, by the path each check reports under
func AssertLogContract(t *testing.T, opts ...LogOption) {
	t.Helper()
	cfg := newLogConfig(opts...)
	if len(cfg.subjects) == 0 {
		t.Fatalf("AssertLogContract was given no subject; declare one with " +
			"LogSubject(name, factory)")
	}
	for _, p := range cfg.phantoms() {
		t.Errorf("LogWithout(%q) declines nothing: no check here reports "+
			"under that path, so this suite asserts one thing more than its "+
			"author believes", p)
	}
	for _, s := range cfg.subjects {
		runLogChecks(t, cfg, s.name, s.factory, nil)
	}
}

// runLogChecks runs the whole contract against one subject.
//
// wrap is applied after the subject is built and seeded, so a wrapper is
// transparent to the seed and every failure it causes is its own.
func runLogChecks(
	t *testing.T,
	cfg *logConfig,
	label string,
	factory func() causalchain.Log,
	wrap func(tb testing.TB, subject causalchain.Log) causalchain.Log,
) {
	t.Helper()
	t.Run(label, func(t *testing.T) {
		t.Parallel()

		t.Run(logAppend, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onAppend {
				cfg.run(t, string(suite.MethodID(logAppend, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap), cfg.Fixture.Entry)
				})
			}
		})

		t.Run(logReplay, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onReplay {
				cfg.run(t, string(suite.MethodID(logReplay, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap))
				})
			}
		})

		// The extra bodies of checks this run was given, each reporting under its
		// own name and dropped by it.
		//
		// The plain subject only. The wrapped pass exists to prove the double
		// faithful and the per-method checks above already do that, so running one
		// through the wrapper prices the wrapper and says nothing new about the
		// subject.
		if wrap == nil {
			for _, e := range cfg.extensions {
				if cfg.declined(e.name) {
					t.Run(e.name, func(t *testing.T) {
						t.Skipf("dropped through LogWithout(%q)", e.name)
					})
					continue
				}
				t.Run(e.name, func(t *testing.T) {
					t.Parallel()
					e.run(t, label, factory, cfg)
				})
			}
		}
	})
}

